mkuse!{use rustc_index :: IndexVec ;}
mkuse!{use rustc_middle :: mir :: { BasicBlock , Body } ;}
mkuse!{use super :: { Analysis , ResultsCursor } ;}
mkitem!{# [doc = " The results of a dataflow analysis that has converged to fixpoint. It only holds the domain"] # [doc = " values at the entry of each basic block. Domain values in other parts of the block are"] # [doc = " recomputed on the fly by visitors (i.e. `ResultsCursor`, or `ResultsVisitor` impls)."] pub type Results < D > = IndexVec < BasicBlock , D > ;}
mkitem!{mkstruct!{# [doc = " Utility type used in a few places where it's convenient to bundle an analysis with its results."] pub struct AnalysisAndResults < 'tcx , A > where A : Analysis < 'tcx > , { pub analysis : A , pub results : Results < A :: Domain > , }}}
mkitem!{mkimpl!{impl < 'tcx , A > AnalysisAndResults < 'tcx , A > where A : Analysis < 'tcx > , { # [doc = " Creates a `ResultsCursor` that takes ownership of `self`."] pub fn into_results_cursor < 'mir > (self , body : & 'mir Body < 'tcx >) -> ResultsCursor < 'mir , 'tcx , A > { ResultsCursor :: new_owning (body , self . analysis , self . results) } }}}